def build_agent(sandbox):
    # Create a single beam at x=6.0, y=1.0 to guide particles
    beam = sandbox.add_beam(x=6.0, y=1.0, width=0.1, height=1.2, density=250.0)
    joint = sandbox.add_joint(beam, body_b=None, anchor_point=(6.0, 1.0), type='rigid')
    return beam

def agent_action(sandbox, agent_body, step_count):
    particles = sandbox.get_fluid_particles()
    for particle in particles:
        x, y = particle.position.x, particle.position.y
        fx, fy = 0.0, 0.0

        # Source area: push right and up
        if x < 6.0:
            fx = 10.0
            fy = 10.0
        # Gravity well: push upward
        elif 10.0 <= x <= 14.0 and 1.5 <= y <= 3.5:
            fy = 10.0
        # Headwind area: push rightward
        elif y >= 3.0:
            fx = 10.0
        # General movement: push toward target
        else:
            fx = 10.0
            fy = 10.0

        # Avoid pits by pushing upward
        if 13.5 <= x <= 15.5 and 0.0 <= y <= 2.0:
            fy = 10.0
        elif 16.0 <= x <= 17.5 and 0.0 <= y <= 1.6:
            fy = 10.0
        elif 11.0 <= x <= 12.5 and 0.0 <= y <= 1.6:
            fy = 10.0

        # Apply force to the particle
        sandbox.apply_force_to_particle(particle, fx, fy)
